(BINARY t.`Data16` <=> BINARY b.`Data16`) AND (BINARY t.`Data17` <=> BINARY b.`Data17`) AND (BINARY t.`Data18` <=> BINARY b.`Data18`) AND (BINARY t.`Data19` <=> BINARY b.`Data19`) AND (BINARY t.`Data20` <=> BINARY b.`Data20`) AND (BINARY t.`Data21` <=> BINARY b.`Data21`) AND (BINARY t.`Data22` <=> BINARY b.`Data22`) AND (BINARY t.`Data23` <=> BINARY b.`Data23`) AND (BINARY t.`Data24` <=> BINARY b.`Data24`) AND (BINARY t.`Data25` <=> BINARY b.`Data25`) AND (BINARY t.`Data26` <=> BINARY b.`Data26`) AND (BINARY t.`Data27` <=> BINARY b.`Data27`) AND (BINARY t.`Data28` <=> BINARY b.`Data28`) AND (BINARY t.`Data29` <=> BINARY b.`Data29`) AND (BINARY t.`Data30` <=> BINARY b.`Data30`) AND (BINARY t.`Data31` <=> BINARY b.`Data31`) AND (BINARY t.`Data32` <=> BINARY b.`Data32`) AND (BINARY t.`RequiredLevel` <=> BINARY b.`RequiredLevel`) AND (BINARY t.`AIName` <=> BINARY b.`AIName`) AND (BINARY t.`ScriptName` <=> BINARY b.`ScriptName`)))) LIMIT 1;
