-- Native GOOBER cages: preserve source models, flags and AnimationData IDs.
-- Requires visual schema2026_10_05_03 and state-animation schema2026_10_08_00 plus rebuilt core.
-- NPC AI, spawns, quest objectives and the existing release flags are not modified.
DROP TEMPORARY TABLE IF EXISTS `_1kycore_cage_guard`, `_1kycore_cage_native`, `_1kycore_cage_baseline`, `_1kycore_cage_addons`;
CREATE TEMPORARY TABLE `_1kycore_cage_guard` (ok INT PRIMARY KEY);
CREATE TEMPORARY TABLE `_1kycore_cage_native` LIKE `gameobject_template`;
CREATE TEMPORARY TABLE `_1kycore_cage_baseline` LIKE `gameobject_template`;
CREATE TEMPORARY TABLE `_1kycore_cage_addons` LIKE `gameobject_template_addon`;
UPDATE gameobject_template_addon a JOIN `_1kycore_cage_addons` n ON n.entry=a.entry SET a.`faction`=n.`faction`,a.`flags`=n.`flags`,a.`mingold`=n.`mingold`,a.`maxgold`=n.`maxgold`,a.`WorldEffectID`=n.`WorldEffectID`,a.`SpellVisualID`=n.`SpellVisualID`,a.`SpellStateVisualID`=n.`SpellStateVisualID`,a.`StateWorldEffectID`=n.`StateWorldEffectID`,a.`SpellStateAnimID`=n.`SpellStateAnimID` WHERE (a.`faction`=0 AND a.`flags`=0 AND a.`mingold`=0 AND a.`maxgold`=0 AND a.`WorldEffectID`=0 AND a.`SpellVisualID`=0 AND a.`SpellStateVisualID`=0 AND a.`StateWorldEffectID`=0 AND a.`SpellStateAnimID`=0);
UPDATE gameobject_template a JOIN `_1kycore_cage_native` n ON n.entry=a.entry JOIN `_1kycore_cage_baseline` b ON b.entry=a.entry SET a.`type`=n.`type`,a.`displayId`=n.`displayId`,a.`name`=n.`name`,a.`IconName`=n.`IconName`,a.`castBarCaption`=n.`castBarCaption`,a.`unk1`=n.`unk1`,a.`size`=n.`size`,a.`Data0`=n.`Data0`,a.`Data1`=n.`Data1`,a.`Data2`=n.`Data2`,a.`Data3`=n.`Data3`,a.`Data4`=n.`Data4`,a.`Data5`=n.`Data5`,a.`Data6`=n.`Data6`,a.`Data7`=n.`Data7`,a.`Data8`=n.`Data8`,a.`Data9`=n.`Data9`,a.`Data10`=n.`Data10`,a.`Data11`=n.`Data11`,a.`Data12`=n.`Data12`,a.`Data13`=n.`Data13`,a.`Data14`=n.`Data14`,a.`Data15`=n.`Data15`,a.`Data16`=n.`Data16`,a.`Data17`=n.`Data17`,a.`Data18`=n.`Data18`,a.`Data19`=n.`Data19`,a.`Data20`=n.`Data20`,a.`Data21`=n.`Data21`,a.`Data22`=n.`Data22`,a.`Data23`=n.`Data23`,a.`Data24`=n.`Data24`,a.`Data25`=n.`Data25`,a.`Data26`=n.`Data26`,a.`Data27`=n.`Data27`,a.`Data28`=n.`Data28`,a.`Data29`=n.`Data29`,a.`Data30`=n.`Data30`,a.`Data31`=n.`Data31`,a.`Data32`=n.`Data32`,a.`RequiredLevel`=n.`RequiredLevel`,a.`AIName`=n.`AIName`,a.`ScriptName`=n.`ScriptName` WHERE ((BINARY a.`type` <=> BINARY b.`type`) AND (BINARY a.`displayId` <=> BINARY b.`displayId`) AND (BINARY a.`name` <=> BINARY b.`name`) AND (BINARY a.`IconName` <=> BINARY b.`IconName`) AND (BINARY a.`castBarCaption` <=> BINARY b.`castBarCaption`) AND (BINARY a.`unk1` <=> BINARY b.`unk1`) AND (ABS(a.`size`-b.`size`)<=0.000001) AND (BINARY a.`Data0` <=> BINARY b.`Data0`) AND (BINARY a.`Data1` <=> BINARY b.`Data1`) AND (BINARY a.`Data2` <=> BINARY b.`Data2`) AND (BINARY a.`Data3` <=> BINARY b.`Data3`) AND (BINARY a.`Data4` <=> BINARY b.`Data4`) AND (BINARY a.`Data5` <=> BINARY b.`Data5`) AND (BINARY a.`Data6` <=> BINARY b.`Data6`) AND (BINARY a.`Data7` <=> BINARY b.`Data7`) AND (BINARY a.`Data8` <=> BINARY b.`Data8`) AND (BINARY a.`Data9` <=> BINARY b.`Data9`) AND (BINARY a.`Data10` <=> BINARY b.`Data10`) AND (BINARY a.`Data11` <=> BINARY b.`Data11`) AND (BINARY a.`Data12` <=> BINARY b.`Data12`) AND (BINARY a.`Data13` <=> BINARY b.`Data13`) AND (BINARY a.`Data14` <=> BINARY b.`Data14`) AND (BINARY a.`Data15` <=> BINARY b.`Data15`) AND (BINARY a.`Data16` <=> BINARY b.`Data16`) AND (BINARY a.`Data17` <=> BINARY b.`Data17`) AND (BINARY a.`Data18` <=> BINARY b.`Data18`) AND (BINARY a.`Data19` <=> BINARY b.`Data19`) AND (BINARY a.`Data20` <=> BINARY b.`Data20`) AND (BINARY a.`Data21` <=> BINARY b.`Data21`) AND (BINARY a.`Data22` <=> BINARY b.`Data22`) AND (BINARY a.`Data23` <=> BINARY b.`Data23`) AND (BINARY a.`Data24` <=> BINARY b.`Data24`) AND (BINARY a.`Data25` <=> BINARY b.`Data25`) AND (BINARY a.`Data26` <=> BINARY b.`Data26`) AND (BINARY a.`Data27` <=> BINARY b.`Data27`) AND (BINARY a.`Data28` <=> BINARY b.`Data28`) AND (BINARY a.`Data29` <=> BINARY b.`Data29`) AND (BINARY a.`Data30` <=> BINARY b.`Data30`) AND (BINARY a.`Data31` <=> BINARY b.`Data31`) AND (BINARY a.`Data32` <=> BINARY b.`Data32`) AND (BINARY a.`RequiredLevel` <=> BINARY b.`RequiredLevel`) AND (BINARY a.`AIName` <=> BINARY b.`AIName`) AND (BINARY a.`ScriptName` <=> BINARY b.`ScriptName`));
DROP TEMPORARY TABLE `_1kycore_cage_guard`, `_1kycore_cage_native`, `_1kycore_cage_baseline`, `_1kycore_cage_addons`;
